/**
 * Produces a bounded set of deterministic RDF-term probes for one typed RDF value.
 *
 * <p>
 * Frontier's mapped columns are keyed by RDF term id, while SPARQL value equality admits multiple lexical forms and,
 * for numerics, multiple datatypes. The candidates here are only a lower-support probe set: every generated term is
 * validated with the query evaluator before it can contribute, and absence never proves that the filter is empty. This
 * recovers common Java-value factory forms without enumerating the value dictionary or statement indexes.
 * </p>
 */
final class LmdbTypedValueProbeSupport {

	private static final int MAX_PROBE_VALUES_PER_VALUE = 16;
	private static final ValueFactory VALUE_FACTORY = SimpleValueFactory.getInstance();

	private LmdbTypedValueProbeSupport() {
	}

	static Set<Map<String, Value>> expandEquivalentBindings(Set<Map<String, Value>> bindings, int maximumBindings) {
		if (bindings == null || maximumBindings <= 0) {
			return null;
		}
		Set<Map<String, Value>> expanded = new LinkedHashSet<>();
		for (Map<String, Value> binding : bindings) {
			List<String> names = binding.keySet().stream().sorted().toList();
			if (!expandBinding(binding, names, 0, new LinkedHashMap<>(), expanded, maximumBindings)) {
				return null;
			}
		}
		return expanded;
	}

	static List<Value> equivalentProbeValues(Value value) {
		LinkedHashSet<Value> candidates = new LinkedHashSet<>();
		candidates.add(value);
		if (!(value instanceof Literal literal)) {
			return List.copyOf(candidates);
		}
		CoreDatatype.XSD datatype = literal.getCoreDatatype().asXSDDatatypeOrNull();
		if (datatype == null) {
			return List.copyOf(candidates);
		}
		try {
			if (datatype.isCalendarDatatype()) {
				addTemporalCandidates(candidates, literal, datatype);
			} else if (datatype == CoreDatatype.XSD.BOOLEAN) {
				addIfEquivalent(candidates, literal,
						VALUE_FACTORY.createLiteral(Boolean.toString(literal.booleanValue()), literal.getDatatype()));
			} else if (datatype.isNumericDatatype()) {
				addNumericCandidates(candidates, literal, datatype);
			}
		} catch (IllegalArgumentException | DateTimeException | UnsupportedOperationException ignored) {
			/* An invalid or unsupported typed literal still retains its exact RDF-term probe. */
		}
		return List.copyOf(candidates);
	}

	private static boolean expandBinding(Map<String, Value> source, List<String> names, int ordinal,
			Map<String, Value> current, Set<Map<String, Value>> expanded, int maximumBindings) {
		if (ordinal == names.size()) {
			expanded.add(Map.copyOf(current));
			return expanded.size() <= maximumBindings;
		}
		String name = names.get(ordinal);
		Value value = source.get(name);
		if (value == null) {
			return false;
		}
		for (Value candidate : equivalentProbeValues(value)) {
			current.put(name, candidate);
			if (!expandBinding(source, names, ordinal + 1, current, expanded, maximumBindings)) {
				return false;
			}
		}
		current.remove(name);
		return true;
	}

	private static void addTemporalCandidates(LinkedHashSet<Value> candidates, Literal literal,
			CoreDatatype.XSD datatype) {
		TemporalAccessor value = literal.temporalAccessorValue();
		addIfEquivalent(candidates, literal, VALUE_FACTORY.createLiteral(value));
		switch (datatype) {
		case TIME:
			addTemporal(candidates, literal, () -> LocalTime.from(value));
			addTemporal(candidates, literal, () -> OffsetTime.from(value));
			break;
		case DATE:
			addTemporal(candidates, literal, () -> LocalDate.from(value));
			break;
		case DATETIME:
		case DATETIMESTAMP:
			addTemporal(candidates, literal, () -> LocalDateTime.from(value));
			addTemporal(candidates, literal, () -> OffsetDateTime.from(value));
			addTemporal(candidates, literal, () -> Instant.from(value));
			break;
		case GYEARMONTH:
			addTemporal(candidates, literal, () -> YearMonth.from(value));
			break;
		case GYEAR:
			addTemporal(candidates, literal, () -> Year.from(value));
			break;
		case GMONTHDAY:
			addTemporal(candidates, literal, () -> MonthDay.from(value));
			break;
		case GMONTH:
			addTemporal(candidates, literal, () -> Month.from(value));
			break;
		default:
			break;
		}
	}

	private static void addNumericCandidates(LinkedHashSet<Value> candidates, Literal literal,
			CoreDatatype.XSD datatype) {
		if (datatype.isIntegerDatatype()) {
			BigInteger integer = literal.integerValue();
			addIfEquivalent(candidates, literal,
					VALUE_FACTORY.createLiteral(integer.toString(), literal.getDatatype()));
			addIfEquivalent(candidates, literal, VALUE_FACTORY.createLiteral(integer));
			addIntegralFactoryCandidates(candidates, literal, integer);
			addIfEquivalent(candidates, literal, VALUE_FACTORY.createLiteral(new BigDecimal(integer)));
			return;
		}
		if (datatype == CoreDatatype.XSD.DECIMAL) {
			BigDecimal decimal = literal.decimalValue();
			addIfEquivalent(candidates, literal,
					VALUE_FACTORY.createLiteral(decimal.toPlainString(), literal.getDatatype()));
			addIfEquivalent(candidates, literal, VALUE_FACTORY.createLiteral(decimal.stripTrailingZeros()));
			try {
				BigInteger integer = decimal.toBigIntegerExact();
				addIfEquivalent(candidates, literal, VALUE_FACTORY.createLiteral(integer));
				addIntegralFactoryCandidates(candidates, literal, integer);
			} catch (ArithmeticException ignored) {
				/* Non-integral decimals have no exact Java integer representation. */
			}
			return;
		}
		if (datatype == CoreDatatype.XSD.FLOAT) {
			addIfEquivalent(candidates, literal, VALUE_FACTORY.createLiteral(literal.floatValue()));
		} else if (datatype == CoreDatatype.XSD.DOUBLE) {
			addIfEquivalent(candidates, literal, VALUE_FACTORY.createLiteral(literal.doubleValue()));
		}
	}

	private static void addIntegralFactoryCandidates(LinkedHashSet<Value> candidates, Literal original,
			BigInteger integer) {
		if (integer.bitLength() < Byte.SIZE) {
			addIfEquivalent(candidates, original, VALUE_FACTORY.createLiteral(integer.byteValue()));
		}
		if (integer.bitLength() < Short.SIZE) {
			addIfEquivalent(candidates, original, VALUE_FACTORY.createLiteral(integer.shortValue()));
		}
		if (integer.bitLength() < Integer.SIZE) {
			addIfEquivalent(candidates, original, VALUE_FACTORY.createLiteral(integer.intValue()));
		}
		if (integer.bitLength() < Long.SIZE) {
			addIfEquivalent(candidates, original, VALUE_FACTORY.createLiteral(integer.longValue()));
		}
	}

	private static void addTemporal(LinkedHashSet<Value> candidates, Literal original,
			TemporalSupplier supplier) {
		try {
			addIfEquivalent(candidates, original, VALUE_FACTORY.createLiteral(supplier.get()));
		} catch (DateTimeException | IllegalArgumentException ignored) {
			/* The concrete Java temporal representation does not apply to this XML Schema value. */
		}
	}

	private static void addIfEquivalent(LinkedHashSet<Value> candidates, Literal original, Value candidate) {
		if (candidates.size() >= MAX_PROBE_VALUES_PER_VALUE || candidate == null) {
			return;
		}
		if (candidate.equals(original)
				|| QueryEvaluationUtility.compare(candidate, original, Compare.CompareOp.EQ).orElse(false)) {
			candidates.add(candidate);
		}
	}

	@FunctionalInterface
	private interface TemporalSupplier {
		TemporalAccessor get();
	}
}
